CREATE TABLE IF NOT EXISTS digimon_combat_profiles (
 technique_id INT UNSIGNED PRIMARY KEY, mode VARCHAR(12) NOT NULL,
 primary_spell INT UNSIGNED NOT NULL, secondary_spell INT UNSIGNED NOT NULL, utility_spell INT UNSIGNED NOT NULL,
 hits TINYINT UNSIGNED NOT NULL, duration_ms INT UNSIGNED NOT NULL, range_yards FLOAT NOT NULL,
 radius_yards FLOAT NOT NULL, base_value FLOAT NOT NULL, per_level FLOAT NOT NULL, weapon_factor FLOAT NOT NULL,
 focus_cost TINYINT UNSIGNED NOT NULL,
 FOREIGN KEY(technique_id) REFERENCES digimon_techniques(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
